 *
 * Emulator for Silergy SY24561 fuel gauge
 */

#define DT_DRV_COMPAT silergy_sy24561

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(silergy_sy24561);

#include <zephyr/device.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/sys/byteorder.h>

// Define some placeholder registers for the SY24561
// These are not actual SY24561 registers, but internal emulator registers
// that map to the fuel_gauge API properties used in the test.
#define SY24561_REG_VOLTAGE                 0x08 // Corresponds to SBS Voltage()
#define SY24561_REG_RSOC                    0x0D // Corresponds to SBS RelativeStateOfCharge()
#define SY24561_REG_STATUS                  0x16 // Corresponds to SBS BatteryStatus()
#define SY24561_REG_CURRENT_DIRECTION       0x0A // Corresponds to SBS AverageCurrent() (0 for no current)
#define SY24561_REG_TEMPERATURE             0x09 // Corresponds to SBS Temperature()
#define SY24561_REG_SOC_ALARM               0x01 // Corresponds to SBS RemainingCapacityAlarm()
#define SY24561_REG_CRATE                   0x04 // Placeholder for Crate, similar to MAX17048

static int crate_value = 0x4000; // Default value, similar to MAX17048

void emul_sy24561_set_crate_status(int value)
{
	crate_value = value;
}

/** Static configuration for the emulator */
struct sy24561_emul_cfg {
	/** I2C address of emulator */
	uint16_t addr;
};

/** Run-time data used by the emulator */
struct sy24561_emul_data {
	/** Current register values */
	uint16_t regs[0xFF]; // A simple array to hold register values
};

static int emul_sy24561_reg_write(const struct emul *target, int reg, uint16_t val)
{
	struct sy24561_emul_data *data = target->data;

	switch (reg) {
	case SY24561_REG_TEMPERATURE:
	case SY24561_REG_SOC_ALARM:
		data->regs[reg] = val;
		break;
	default:
		LOG_ERR("Unknown or read-only register 0x%x write", reg);
		return -EIO;
	}

	LOG_DBG("write 0x%x = 0x%x", reg, val);
	return 0;
}

static int emul_sy24561_reg_read(const struct emul *target, int reg, uint16_t *val)
{
	struct sy24561_emul_data *data = target->data;

	switch (reg) {
	case SY24561_REG_VOLTAGE:
		*val = 3199; // 3.199V in mV
		break;
	case SY24561_REG_RSOC:
		*val = 74; // 74%
		break;
	case SY24561_REG_STATUS:
		*val = 0;
		break;
	case SY24561_REG_CURRENT_DIRECTION:
		*val = 0;
		break;
	case SY24561_REG_CRATE:
		*val = crate_value;
		break;
	case SY24561_REG_TEMPERATURE:
		// Return the last written value, or a default if not set
		*val = data->regs[reg] ? data->regs[reg] : 2980; // Default 25C (298.15K * 10)
		break;
	case SY24561_REG_SOC_ALARM:
		// Return the last written value, or a default if not set
		*val = data->regs[reg] ? data->regs[reg] : 10; // Default 10%
		break;
	default:
		LOG_ERR("Unknown register 0x%x read", reg);
		return -EIO;
	}
	LOG_DBG("read 0x%x = 0x%x", reg, *val);

	return 0;
}

static int sy24561_emul_transfer_i2c(const struct emul *target, struct i2c_msg *msgs,
				       int num_msgs, int addr)
{
	uint16_t val;
	int reg;
	int rc;
	const struct sy24561_emul_cfg *cfg = target->cfg;

	__ASSERT_NO_MSG(msgs && num_msgs);

	if (cfg->addr != addr) {
		LOG_ERR("Address mismatch, expected %02x, got %02x", cfg->addr, addr);
		return -EIO;
	}

	i2c_dump_msgs_rw(target->dev, msgs, num_msgs, addr, false);
	switch (num_msgs) {
	case 2:
		if (msgs->flags & I2C_MSG_READ) {
			LOG_ERR("Unexpected read");
			return -EIO;
		}
		if (msgs->len != 1) {
			LOG_ERR("Unexpected msg0 length %d", msgs->len);
			return -EIO;
		}
		reg = msgs->buf[0];

		/* Now process the 'read' part of the message */
		msgs++;
		if (msgs->flags & I2C_MSG_READ) {
			if (msgs->len != 2) { // SBS commands typically read 2 bytes
				LOG_ERR("Unexpected msg1 length %d", msgs->len);
				return -EIO;
			}
			rc = emul_sy24561_reg_read(target, reg, &val);
			if (rc) {
				return rc;
			}
			sys_put_le16(val, msgs->buf);
		} else {
			/* We write a word (2 bytes by the SBS spec) */
			if (msgs->len != 2) {
				LOG_ERR("Unexpected msg1 length %d", msgs->len);
				return -EIO;
			}
			uint16_t value_to_write = sys_get_le16(msgs->buf);
			rc = emul_sy24561_reg_write(target, reg, value_to_write);
		}
		break;
	default:
		LOG_ERR("Invalid number of messages: %d", num_msgs);
		return -EIO;
	}

	return rc;
}

static const struct i2c_emul_api sy24561_emul_api_i2c = {
	.transfer = sy24561_emul_transfer_i2c,
};

/**
 * Set up a new emulator (I2C)
 *
 * @param target Emulation information
 * @param parent Device to emulate
 * @return 0 indicating success (always)
 */
static int emul_sy24561_init(const struct emul *target, const struct device *parent)
{
	ARG_UNUSED(parent);
	struct sy24561_emul_data *data = target->data;
	memset(data->regs, 0, sizeof(data->regs)); // Initialize registers to 0

	return 0;
}

/*
 * Main instantiation macro.
 */
#define SY24561_EMUL(n)                                                                            \
	static struct sy24561_emul_data sy24561_emul_data_##n;                                     \
	static const struct sy24561_emul_cfg sy24561_emul_cfg_##n = {                              \
		.addr = DT_INST_REG_ADDR(n),                                                       \
	};                                                                                         \
	EMUL_DT_INST_DEFINE(n, emul_sy24561_init, &sy24561_emul_data_##n,                          \
			    &sy24561_emul_cfg_##n, &sy24561_emul_api_i2c, NULL)

DT_INST_FOREACH_STATUS_OKAY(SY24561_EMUL)
